import{_ as t,o as r,c as s,ak as n,aq as o,ar as i,as as a,at as l,au as u,av as c}from"./chunks/framework.gO8r5hi3.js";const j=JSON.parse('{"title":"Introduction à Unity","description":"","frontmatter":{},"headers":[],"relativePath":"01_Installation_InterfaceUnity.md","filePath":"01_Installation_InterfaceUnity.md","lastUpdated":1769021325000}'),p={name:"01_Installation_InterfaceUnity.md"};function d(m,e,g,f,v,h){return r(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="introduction-a-unity" tabindex="-1">Introduction à Unity <a class="header-anchor" href="#introduction-a-unity" aria-label="Permalink to “Introduction à Unity”">​</a></h1><p>Unity est un moteur de jeu puissant et polyvalent utilisé pour créer des jeux vidéo et des expériences interactives en 2D et 3D. Cette introduction couvre les bases de l&#39;interface utilisateur, la création de projets, l&#39;importation d&#39;assets, et les concepts fondamentaux nécessaires pour commencer à développer avec Unity.</p><p>Ce n&#39;est pas le seul moteur de jeu. D&#39;autres moteurs populaires incluent Unreal Engine, Godot, et CryEngine. Chacun a ses propres avantages et inconvénients, mais Unity est particulièrement apprécié pour sa facilité d&#39;utilisation, sa large communauté, et son support multiplateforme. Il est rapide à apprendre, même pour les débutants, et offre une grande flexibilité pour les développeurs expérimentés.</p><p>Unity permet de créer à la fois des jeux en 2D et en 3D. Les jeux 2D utilisent des sprites (images plates) et se déroulent généralement sur un plan bidimensionnel, tandis que les jeux 3D utilisent des modèles tridimensionnels et offrent une profondeur supplémentaire.</p><h2 id="jeux-professionnels-realises-avec-unity" tabindex="-1">Jeux professionnels réalisés avec Unity <a class="header-anchor" href="#jeux-professionnels-realises-avec-unity" aria-label="Permalink to “Jeux professionnels réalisés avec Unity”">​</a></h2><ul><li><strong>Hollow Knight</strong> : Un jeu d&#39;action-aventure en 2D acclamé pour son design artistique et son gameplay.</li><li><strong>Cuphead</strong> : Un jeu de plateforme en 2D connu pour son style visuel inspiré des dessins animés des années 1930.</li><li><strong>Ori and the Blind Forest</strong> : Un jeu de plateforme en 2D avec une narration émotionnelle et des graphismes magnifiques.</li><li><strong>Monument Valley</strong> : Un jeu de puzzle en 3D avec des niveaux artistiques et des illusions d&#39;optique.</li><li><strong>Subnautica</strong> : Un jeu d&#39;exploration en 3D sous-marine avec un monde ouvert immersif.</li><li><strong>Pokémon Go</strong> : Un jeu mobile en réalité augmentée qui utilise Unity pour créer des expériences interactives dans le monde réel.</li><li><strong>Beat Saber</strong> : Un jeu de réalité virtuelle en 3D où les joueurs coupent des blocs au rythme de la musique.</li><li><strong>Rust</strong> : Un jeu de survie en ligne en 3D avec un monde ouvert et des interactions multijoueurs.</li><li><strong>Among Us</strong> : Un jeu multijoueur en 2D où les joueurs doivent identifier les imposteurs parmi eux.</li><li><strong>Hearthstone</strong> : Un jeu de cartes à collectionner en ligne en 2D avec des mécaniques de jeu stratégiques.</li><li><strong>Cult of the Lamb</strong> : Un jeu d&#39;action-aventure en 2D avec des éléments de gestion de base et un style artistique unique.</li></ul><h2 id="langage-c" tabindex="-1">Langage C# <a class="header-anchor" href="#langage-c" aria-label="Permalink to “Langage C#”">​</a></h2><p>Unity utilise principalement le langage de programmation C# pour le développement de scripts. C# est un langage orienté objet, moderne et puissant, qui permet de créer des comportements complexes pour les jeux. Il est recommandé d&#39;avoir une compréhension de base de la programmation pour tirer le meilleur parti de Unity.</p><p>Comme JavaScript appris la session dernière, C# utilise des concepts similaires tels que les variables, les fonctions, les boucles, et les conditions. Cependant, C# est plus strict en termes de typage et de structure, ce qui peut aider à prévenir certaines erreurs courantes.</p><p>Nous aborderons les concepts de base de C# au fur et à mesure que nous progressons dans les exercices et les projets Unity.</p><h2 id="configuration-requise" tabindex="-1">Configuration requise <a class="header-anchor" href="#configuration-requise" aria-label="Permalink to “Configuration requise”">​</a></h2><p>Pour utiliser Unity, assurez-vous que votre ordinateur répond aux exigences minimales suivantes :</p><ul><li>Système d&#39;exploitation : Windows 10 (64 bits) ou macOS 10.14+</li><li>Processeur : Processeur multi-cœur avec prise en charge de SSE2</li><li>Mémoire RAM : 8 Go minimum (16 Go recommandé)</li><li>Carte graphique : Compatible DirectX 11 ou Metal</li><li>Espace disque : Au moins 10 Go d&#39;espace libre pour l&#39;installation de Unity</li><li>Connexion Internet : Requise pour l&#39;installation et les mises à jour</li></ul><h2 id="installation-de-unity" tabindex="-1">Installation de Unity <a class="header-anchor" href="#installation-de-unity" aria-label="Permalink to “Installation de Unity”">​</a></h2><ol><li>Aller sur le site officiel de Unity : <a href="https://unity.com/" target="_blank" rel="noreferrer">https://unity.com/</a></li><li>Télécharger et installer <strong>Unity Hub</strong>, un gestionnaire de versions et de projets Unity.</li><li>Ouvrir Unity Hub et créer <strong>un compte Unity</strong> si vous n&#39;en avez pas déjà un.</li><li>Dans Unity Hub, aller à l&#39;onglet <strong>Installs &gt; Install Editor</strong>.</li><li>Dans le panneau, sélectionner l&#39;onglet <strong>Official Releases</strong>. Choisir la version <strong>6.3 LTS (6000.3.5f1)</strong> et cliquer sur <strong>Install</strong>.</li><li>Sélectionner les modules supplémentaires nécessaires, tels que le support pour les plateformes spécifiques (Windows, macOS, Android, iOS, etc.). Assurez-vous d&#39;inclure le module <strong>Visual Studio Community</strong> pour le développement de scripts C# et le module <strong>WebGL build support</strong> pour la compilation web. Au besoin, vous pouvez ajouter d&#39;autres modules plus tard.</li></ol><p><img src="'+o+'" alt="Installation Unity Hub"></p><p><img src="'+i+'" alt="Ajouter un module"></p><h2 id="creation-d-un-nouveau-projet" tabindex="-1">Création d&#39;un nouveau projet <a class="header-anchor" href="#creation-d-un-nouveau-projet" aria-label="Permalink to “Création d&#39;un nouveau projet”">​</a></h2><p>Pour créer un nouveau projet Unity</p><ol><li>Ouvrir <strong>Unity Hub</strong></li><li>Aller à l&#39;onglet <strong>Projects</strong></li><li>Cliquer sur <strong>New Project</strong></li><li>Sélectionner le template <strong>Universel 2D Core</strong> pour nos projets 2D</li><li>Nommer le projet de manière appropriée (exemple : &quot;VotreNom_ExFlappyBird&quot;)</li><li>Choisir un emplacement pour sauvegarder le projet. <strong>NE PAS utiliser OneDrive ou un dossier synchronisé en ligne.</strong></li></ol><p><img src="'+a+'" alt="Créer un nouveau projet"></p><h2 id="importer-un-projet-existant" tabindex="-1">Importer un projet existant <a class="header-anchor" href="#importer-un-projet-existant" aria-label="Permalink to “Importer un projet existant”">​</a></h2><p>Pour ouvrir un projet Unity existant:</p><ol><li>Ouvrir <strong>Unity Hub</strong></li><li>Aller à l&#39;onglet <strong>Projects</strong></li><li>Cliquer sur <strong>Add</strong></li><li>Naviguer jusqu&#39;au dossier du projet Unity existant</li><li>Sélectionner le dossier et cliquer sur <strong>Select Folder</strong></li><li>Le projet apparaîtra maintenant dans la liste des projets disponibles dans Unity Hub. Cliquer dessus pour l&#39;ouvrir.</li></ol><p>Si votre projet utilise une version différente de Unity que celle installée, Unity Hub vous proposera de télécharger et d&#39;installer la version appropriée. <strong>TRAVAILLEZ TOUJOURS AVEC LA MÊME VERSION DE UNITY entre chez vous et le laboratoire du Collège.</strong></p><h2 id="interfaces-et-fenetres-principales-de-unity" tabindex="-1">Interfaces et fenêtres principales de Unity <a class="header-anchor" href="#interfaces-et-fenetres-principales-de-unity" aria-label="Permalink to “Interfaces et fenêtres principales de Unity”">​</a></h2><p>Une fois dans Unity, vous verrez plusieurs fenêtres principales. Déplacez et organisez-les selon vos préférences, mais voici une description des fenêtres les plus importantes . Si vous ne voyez pas une fenêtre, vous pouvez l&#39;ouvrir via le menu <code>Window</code> en haut. Déplacez les fenêtres pour qu&#39;elles correspondent à cette image.</p><p><img src="'+l+'" alt="Interface Unity"></p><ol><li><strong>Hierarchy</strong> : Cette fenêtre liste tous les objets présents dans la scène actuelle. Vous pouvez organiser les objets en les faisant glisser pour créer des relations parent-enfant. Une scène peut être vue comme un niveau ou un environnement dans lequel le jeu se déroule.</li><li><strong>Scene View</strong> : C&#39;est ici que vous construisez et organisez votre scène de jeu. Vous pouvez y déplacer, faire pivoter et redimensionner les objets. La fenêtre possède une barre d&#39;outils en haut pour naviguer dans la scène (panoramique, zoom, rotation) et manipuler les objets (déplacer, faire pivoter, redimensionner).</li><li><strong>Inspector</strong> : Cette fenêtre affiche les propriétés et les paramètres de l&#39;objet actuellement sélectionné dans la Hierarchy ou le Project. Vous pouvez modifier les composants, les scripts, et d&#39;autres réglages de l&#39;objet ici.</li><li><strong>Project</strong> : Cette fenêtre affiche tous les fichiers et assets de votre projet Unity. C&#39;est ici que vous importez des images, des sons, des scripts, et d&#39;autres ressources nécessaires pour votre jeu.</li><li><strong>Game View</strong> : Cette fenêtre affiche ce que la caméra principale voit dans le jeu. C&#39;est la vue que les joueurs auront lorsqu&#39;ils joueront à votre jeu.</li><li><strong>Console</strong> : Cette fenêtre affiche les messages de débogage, les erreurs, et les avertissements générés par votre jeu ou vos scripts. C&#39;est un outil essentiel pour le développement et le débogage.</li></ol><h3 id="enregistrer-le-positionnement-des-fenetres" tabindex="-1">Enregistrer le positionnement des fenêtres <a class="header-anchor" href="#enregistrer-le-positionnement-des-fenetres" aria-label="Permalink to “Enregistrer le positionnement des fenêtres”">​</a></h3><p>Une fois que vous avez organisé les fenêtres selon vos préférences, vous pouvez enregistrer cette disposition pour une utilisation future :</p><ol><li>Aller dans le menu <code>Window</code> &gt; <code>Layouts</code> &gt; <code>Save Layout...</code></li><li>Donner un nom à votre disposition personnalisée et cliquer sur <code>Save</code></li></ol><p>Si jamais vous souhaitez revenir à cette disposition, vous pouvez la sélectionner dans le menu <code>Window</code> &gt; <code>Layouts</code>.</p><p>L&#39;utilisation de packages Unity permet de partager facilement des assets, scripts, et autres ressources entre différents projets Unity. Cela peut être une façon d&#39;archiver temporairement des éléments ou de les transférer vers un autre projet.</p><p>Les packages peuvent contenir des scripts, des textures, des modèles 3D, des scènes, et bien plus encore.</p><h2 id="ajuster-la-fenetre-game-view" tabindex="-1">Ajuster la fenêtre Game View <a class="header-anchor" href="#ajuster-la-fenetre-game-view" aria-label="Permalink to “Ajuster la fenêtre Game View”">​</a></h2><p><img src="'+u+'" alt="Ajustement de la fenêtre Game View"></p><p>La fenêtre Game View peut être ajustée pour simuler différentes résolutions d&#39;écran. Cela est particulièrement utile pour tester comment votre jeu apparaîtra sur différents appareils. Pour l&#39;instant, sélectionnez la résolution <code>16:9</code> et sélectionnez l&#39;option <code>Play Focussed</code> (icône de cible) pour que la fenêtre Game reste active lorsque vous appuyez sur le bouton Play mais sans être mise en plein écran.</p><p>Si vous trouvez que les graphiques sont flous, décochez l&#39;option <code>Low Resolution Aspect Ratios</code> dans le menu déroulant des résolutions si votre ordinateur le permet.</p><h3 id="ajuster-la-resolution-de-la-fenetre-de-jeu" tabindex="-1">Ajuster la résolution de la fenêtre de jeu <a class="header-anchor" href="#ajuster-la-resolution-de-la-fenetre-de-jeu" aria-label="Permalink to “Ajuster la résolution de la fenêtre de jeu”">​</a></h3><p>Vous devriez toujours tester votre jeu en fonction de la résolution cible prévue. Pour ajouter une résolution personnalisée :</p><ol><li>Cliquer sur le menu déroulant des résolutions dans la fenêtre Game View (par défaut, il peut afficher <code>Free Aspect</code>).</li><li>Sélectionner une résolution prédéfinie ou cliquer sur le signe <code>+</code> pour ajouter une résolution personnalisée.</li><li>Donner un nom à la résolution personnalisée, définir la largeur et la hauteur, puis cliquer sur <code>OK</code>.</li></ol><h3 id="exemples-de-resolutions-courantes" tabindex="-1">Exemples de résolutions courantes <a class="header-anchor" href="#exemples-de-resolutions-courantes" aria-label="Permalink to “Exemples de résolutions courantes”">​</a></h3><ul><li>1920 x 1080 (Écran standard HD)</li><li>1366 x 768 (Écran ordinateur portable)</li><li>768 X 1024 (Tablette - portrait)</li><li>1024 x 768 (Tablette - paysage)</li><li>640 x 360 (Mobile - paysage)</li><li>360 x 640 (Mobile - portrait)</li></ul><p>Pour voir les statistiques de format d&#39;écrans courants: <a href="https://gs.statcounter.com/screen-resolution-stats" target="_blank" rel="noreferrer">https://gs.statcounter.com/screen-resolution-stats</a></p><h3 id="pour-tester-votre-jeu" tabindex="-1">Pour tester votre jeu <a class="header-anchor" href="#pour-tester-votre-jeu" aria-label="Permalink to “Pour tester votre jeu”">​</a></h3><p>Pour tester votre jeu dans l&#39;éditeur Unity, vous pouvez utiliser le bouton <code>Play</code> situé en haut au centre de l&#39;interface. Lorsque vous cliquez sur ce bouton, Unity passe en mode de jeu, et vous pouvez interagir avec votre jeu comme si vous étiez un joueur. Si vous avez cliqué en dehors de la fenêtre Game View pendant le test, recliquez dans cette fenêtre pour lui redonner le focus.</p><h2 id="importer-un-package-unity" tabindex="-1">Importer un package Unity <a class="header-anchor" href="#importer-un-package-unity" aria-label="Permalink to “Importer un package Unity”">​</a></h2><p><img src="'+c+'" alt="Importer un paquet"></p><ol><li>Ouvrir Unity et le projet dans lequel vous souhaitez importer le package.</li><li>Aller dans le menu principal et sélectionner <code>Assets</code> &gt; <code>Import Package</code> &gt; <code>Custom Package...</code>.</li><li>Naviguer jusqu&#39;à l&#39;emplacement du fichier <code>.unitypackage</code> que vous souhaitez importer.</li><li>Sélectionner le fichier et cliquer sur <code>Open</code>.</li><li>Une fenêtre d&#39;importation s&#39;ouvrira, affichant tous les assets contenus dans le package. Vous pouvez cocher ou décocher les éléments que vous souhaitez importer.</li><li>Cliquer sur <code>Import</code> pour commencer l&#39;importation. Les assets seront ajoutés à votre projet Unity.</li></ol><h2 id="exporter-un-package-unity" tabindex="-1">Exporter un package Unity <a class="header-anchor" href="#exporter-un-package-unity" aria-label="Permalink to “Exporter un package Unity”">​</a></h2><ol><li>Ouvrir Unity et le projet contenant les assets que vous souhaitez exporter.</li><li>Dans la fenêtre <code>Project</code>, sélectionner les assets que vous souhaitez inclure dans le package. Vous pouvez sélectionner plusieurs éléments en maintenant la touche <code>Ctrl</code> (ou <code>Cmd</code> sur Mac) enfoncée.</li><li>Aller dans le menu principal et sélectionner <code>Assets</code> &gt; <code>Export Package...</code>.</li><li>Dans la fenêtre d&#39;exportation, vérifier que tous les assets souhaités sont cochés. Si vos assets dépendent d&#39;autres assets, cochez l&#39;option <code>Include dependencies</code>.</li><li>Cliquer sur <code>Export</code> et choisir l&#39;emplacement où enregistrer le fichier <code>.unitypackage</code>.</li><li>Cliquer sur <code>Save</code> pour créer le package.</li></ol><h2 id="documentation-officielle" tabindex="-1">Documentation officielle <a class="header-anchor" href="#documentation-officielle" aria-label="Permalink to “Documentation officielle”">​</a></h2><p>Unity dispose d&#39;une documentation officielle très complète qui couvre tous les aspects du moteur, des concepts de base aux fonctionnalités avancées. Vous pouvez y accéder en ligne à l&#39;adresse suivante : <a href="https://docs.unity3d.com/Manual/index.html" target="_blank" rel="noreferrer">https://docs.unity3d.com/Manual/index.html</a>. Si vous ne vous souvenez plus comment faire quelque chose dans Unity, la documentation est souvent le meilleur endroit pour trouver des réponses.</p><h2 id="ressources-supplementaires" tabindex="-1">Ressources supplémentaires <a class="header-anchor" href="#ressources-supplementaires" aria-label="Permalink to “Ressources supplémentaires”">​</a></h2><ul><li>Liste vidéos du cours : <a href="https://www.youtube.com/watch?v=fiDW-0GYLsg&amp;list=PL0_-lSQN5AZQC3Wd3HTILptbWASZ4AY-z" target="_blank" rel="noreferrer">Vidéos officielles du cours</a></li><li>Tutoriels Unity Learn : <a href="https://learn.unity.com/" target="_blank" rel="noreferrer">https://learn.unity.com/</a></li><li>Chaîne YouTube Unity : <a href="https://www.youtube.com/user/Unity3D" target="_blank" rel="noreferrer">https://www.youtube.com/user/Unity3D</a></li><li>Brackeys Unity Tutorials : <a href="https://www.youtube.com/c/Brackeys" target="_blank" rel="noreferrer">https://www.youtube.com/c/Brackeys</a></li><li>Cours C# pour débutants : <a href="https://learn.microsoft.com/en-us/dotnet/csharp/" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/dotnet/csharp/</a></li></ul>',56)])])}const b=t(p,[["render",d]]);export{j as __pageData,b as default};
